head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00400_00.xml";

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정) 
 */

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    scwin.init();
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 *  기업 검색 팝업화면을 표시한다.
 */
scwin.img_coSearch_onclick = function(e) {
    scwin.comSrchOpen();
};

/**
 *  기업명 입력후 키다운 이벤트 처리
 */
scwin.tbx_coSnm_onkeydown = function(e) {

    if (e.keyCode === 13) {

        if (tbx_coSnm.getValue() === "") {           
            scwin.comSrchOpen(); // 기업검색팝업 오픈
        } else {        
            scwin.comInfoSrch(); // 기업정보 조회
        }

    }
};

/**
 *  엑셀 다운로드 버튼 처리
 */
scwin.btn_excel_onclick = function(e) {

    if ($p.parent().frame_body.getWindow().scwin.fn_excel_download) {
        $p.parent().frame_body.getWindow().scwin.fn_excel_download();
    }

};

/**
 *  라디오 버튼 클릭시 화면명 설정 처리
 */
scwin.rdo_fg_onchange = function (info) {
    scwin.rdoFgOnSelChange();	
};

/**
 *  연결주석 화면별 정보 조회
 */
scwin.btn_search_onclick = function (e) {
    scwin.search();
};

/**
 *  기업 정보 데이터 로드시 기능 처리(기업명으로 조회)
 */
scwin.dlt_comListRes_ondataload = function () {

    // 조회결과가 1개이면 기업개황 조회 아니면 기업팝업 오픈
    if (dlt_comListRes.getRowCount() === 1) {

        // 조회조건에 값을 세팅
        tbx_kisCd.setValue(dlt_comListRes.getCellData(0, "kisCd"));

        // 결산일자 visible = true인 경우
        if (pnl_AcntclsDt.getStyle("display") === "none") {
            // 기업현황 조회
            scwin.search();
        } else {
            // 결산일자 조회
            scwin.srchAcntclsDt();
        }
    } else {
        scwin.comSrchOpen(); //기업검색 팝업 오픈
    }	
};

/**
 *  기업명 입력값이 변경됐을때 이벤트 처리(사용자가 화면의 값을 변경했을때(예 : 입력값 수정, 선택값 변경) 발생)
 */
scwin.tbx_coSnm_onviewchange = function (info) {

    //tbx_coSnm.setValue("");

};

/**
 *  결산일자 항목이 변경되면 기업정보 재조회
 */
scwin.cmb_acntclsDt_onchange = function (info) {

	scwin.search();

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  화면 초기화
 */
scwin.init = function() {

    //라디오 기본값 : 감사의견및특기사항
    rdo_fg.setValue("01");
    // rdo_fg 값에따른 화면 처리
    scwin.rdoFgOnSelChange();

};

/**
 *  조회조건 연결주석항목별 값이 변동될때 로직 처리
 */
scwin.rdoFgOnSelChange = function() {

    const pageNum = rdo_fg.getValue();

    if (pageNum === "01" || pageNum === "02" || pageNum === "03") {
        btn_excel.show();
    } else {
        btn_excel.hide();
    }

    // 라디오 클릭 시 하단 프레임에 적당한 화면 세팅.
    scwin.displayFrame(rdo_fg.getValue());

    // 결산일자 visible
    scwin.displayAcntclsDt();

};

/**
 *  하단 frame에 출력 그리드 설정
 */
scwin.displayFrame = function(pVal) {

    $p.parent().frame_body.setSrc(scwin.getUrl(pVal));

};

/**
 *  프로그램 파일명 경로 설정
 */
scwin.getUrl = function(pVal) {

    const vUrl = "/ui/lst/fis/ULDFIS00400_" + pVal + ".xml";
    return vUrl;

};

/**
 * 결산일자 콤보박스 display 설정(보이기/숨김)
 */
scwin.displayAcntclsDt = function() {

    // 주요주주, 배당, 관계회사현황
    if (rdo_fg.getValue() === "02" || rdo_fg.getValue() === "03" || rdo_fg.getValue() === "04" || rdo_fg.getValue() === "05" ||
        rdo_fg.getValue() === "06" || rdo_fg.getValue() === "07" || rdo_fg.getValue() === "08") {
        pnl_AcntclsDt.setStyle("display", "");
    } else {
        pnl_AcntclsDt.setStyle("display", "none");
    }

};

/**
 *  결산일자 조회
 */
scwin.srchAcntclsDt = async function() {

    //데이터셋 초기화
    scwin.initDs("2");

    // 결산일자 visible = true인 경우만 조회, KisCd 필수
    if (pnl_AcntclsDt.getStyle("display") === "none" || tbx_kisCd.getValue() === "") {
        return;
    }

    dma_consNotesAcntclsDtInfoReq.set("kisCd", tbx_kisCd.getValue()); // 기업코드
    dma_consNotesAcntclsDtInfoReq.set("fg", rdo_fg.getValue()); // 연결주석코드

    const sbmOptions = {
        id : "sbm_consNotesAcntclsDt",
        action : "/api/listing/nice/financial/cons-notes/acntcls-dt",
        method : "get",
        ref : "dma_consNotesAcntclsDtInfoReq",
        target : "dlt_consNotesAcntclsDtListRes|append",
        isProcessMsg : false
    };
    const res = await await $c.sbm.executeDynamic(sbmOptions);
    dlt_consNotesAcntclsDtListRes.setJSON(res.responseJSON.body);

    if (dlt_consNotesAcntclsDtListRes.getRowCount() <= 0) {
        alert("결산일자가 존재하지 않습니다.");
    }

};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    // 필수항목 체크
    if (tbx_coSnm.getValue() === "") {
        alert("기업명을 입력하세요.");
        tbx_coSnm.focus();
        return false;
    }

    if (pnl_AcntclsDt.getStyle("display") !== "none" && cmb_acntclsDt.getValue() === "") {
        alert("결산일자를 입력하세요.");
        cmb_acntclsDt.focus();
        return false;
    }

    // 기업명은 있는데 기업코드가 없는 경우
    if (tbx_coSnm.getValue() !== "" && tbx_kisCd.getValue() === "") {
        scwin.comInfoSrch();
        return false;
    }

    return true;

};

/**
 * 기업현황 조회
 */
scwin.search = function() {

    // 조회조건 필수 체크
    if (!scwin.chkValid()) {
        return;
    }

    if ($p.parent().frame_body.getWindow().scwin.search) {
        $p.parent().frame_body.getWindow().scwin.search();
    }

};

/**
 *  데이터셋 초기화
 */
scwin.initDs = function(pFg) {

    if (pFg === "1") {
        dlt_comListRes.setData([]);
    } else if (pFg === "2") {
        dlt_consNotesAcntclsDtListRes.setData([]);
    }

};

/**
 * 기업정보 조회(명으로 조회)
 */
scwin.comInfoSrch = async function() {

    // 데이터셋 초기화
    scwin.initDs("1");

    // 기업명 없으면 return
    if (tbx_coSnm.getValue() === "") {
        return;
    }

    dma_comInfoReq.set("coSnm", tbx_coSnm.getValue()); // 기업명
    const sbmOptions = {
        id : "sbm_comInfo",
        action : "/api/listing/nice/com-overview/com-info",
        method : "get",
        ref : "dma_comInfoReq",
        target : "dlt_comListRes|append",
        isProcessMsg : false
    };
    const res = await await $c.sbm.executeDynamic(sbmOptions);
    dlt_comListRes.setJSON(res.responseJSON.body);

};

/**
 * 기업검색 팝업 화면을 표시한다.
 */
scwin.comSrchOpen = async function() {

    const url = "/ui/lst/fis/ULDFIS00101.xml";
    const popTitle = "기업 검색";

    const opts = {
        id: "ULDFIS00101",
        popupName: popTitle,
        width: 750,
        height: 490,
        frameModal: "top",
    };

    const res = await $c.win.openPopup(url, opts);

    tbx_coSnm.setValue(res.coSnm); // 기업명
    tbx_kisCd.setValue(res.kisCd); // 기업코드

};

/**
 * 팝업으로 값을 넘김.
 */
scwin.getParKisCd = function() {
    const arrPar = new Array();
    arrPar[0] = tbx_coSnm.getValue(); // 기업명
    return arrPar;
};

/**
 * 기업 겁색 팝업에서 넘어온 값 설정 및 조회 처리
 */
scwin.setParKisCd = function(arrPar) {

    tbx_coSnm.setValue(arrPar[0].coSnm); //기업명
    tbx_kisCd.setValue(arrPar[0].kisCd); //기업코드

    if (tbx_kisCd.getValue() !== "") {
        // 결산일자 visible = true인 경우
        if (pnl_AcntclsDt.getStyle("display") === "none") {
            // 기업현황 조회
            scwin.search();
        } else {
            // 결산일자 조회
            scwin.srchAcntclsDt();
        }
    }

};

/**
 *  조회조건의 기업코드를 리턴
 */
scwin.getKisCd = function() {
    return tbx_kisCd.getValue();
};

/**
 *  조회조건의 결산일자를 리턴
 */
scwin.getAcntclsDt = function() {
    return cmb_acntclsDt.getValue();
};
